function withArtwork(post: BlogPostContent): BlogPostEntry {
  const artwork = BLOG_ARTWORK[post.slug] || {
    imageId: '1503676260728-1c00da094a0b',
    imageAlt: post.title,
    diagram: undefined,
  }

  return {
    ...post,
    imageUrl: `https://images.unsplash.com/photo-${artwork.imageId}?auto=format&fit=crop&w=1200&q=80`,
    imageAlt: artwork.imageAlt,
    diagram: artwork.diagram,
  }
}

export function getAllBlogs(): BlogPostEntry[] {
  return BLOGS_DATA.map(withArtwork)
}

export function getBlogBySlug(slug: string): BlogPostEntry | undefined {
  const post = BLOGS_DATA.find(b => b.slug === slug)
  return post ? withArtwork(post) : undefined
}

export function getBlogsByCategory(category: string): BlogPostEntry[] {
  return BLOGS_DATA
    .filter(b => b.category.toLowerCase() === category.toLowerCase())
    .map(withArtwork)
}

export function searchBlogs(query: string): BlogPostEntry[] {
  const q = query.trim().toLowerCase()
  const results = !q
    ? BLOGS_DATA
    : BLOGS_DATA.filter(b =>
      b.title.toLowerCase().includes(q) ||
      b.excerpt.toLowerCase().includes(q) ||
      b.category.toLowerCase().includes(q) ||
      b.tags.some(t => t.toLowerCase().includes(q))
    )
  return results.map(withArtwork)
}
